def demote(body,idxs):
    hs=list(re.finditer(r'<h2>(.*?)</h2>',body))
    for i in sorted(idxs,reverse=True):
        m=hs[i]; body=body[:m.start()]+'<p><b>'+m.group(1)+'</b></p>'+body[m.end():]
    return body
for f,(extra,dm) in X.items():
    b=d[f]['body']; b=demote(b,dm)
    k=b.rfind('<h2>'); b=b[:k]+extra+'\n'+b[k:]
    d[f]['body']=b
